window.Delta9KupolHTML = "\n\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\"><defs>\n<symbol id=\"i-eye\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1.5 12S5 5 12 5s10.5 7 10.5 7-3.5 7-10.5 7S1.5 12 1.5 12Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></symbol>\n<symbol id=\"i-cam\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 7h3l1.5-2h9L18 7h3v12H3z\"/><circle cx=\"12\" cy=\"13\" r=\"3.6\"/></symbol>\n<symbol id=\"i-gyro\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><ellipse cx=\"12\" cy=\"12\" rx=\"9\" ry=\"3.6\"/><ellipse cx=\"12\" cy=\"12\" rx=\"3.6\" ry=\"9\"/></symbol>\n<symbol id=\"i-geo\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22s7-6.4 7-12a7 7 0 1 0-14 0c0 5.6 7 12 7 12Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.6\"/></symbol>\n<symbol id=\"i-mic\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><rect x=\"9\" y=\"2.5\" width=\"6\" height=\"11\" rx=\"3\"/><path d=\"M5 11a7 7 0 0 0 14 0M12 18v3.5\"/></symbol>\n<symbol id=\"i-target\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 1v4M12 19v4M1 12h4M19 12h4\"/></symbol>\n<symbol id=\"i-stop\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"6\" y=\"6\" width=\"12\" height=\"12\" rx=\"2\"/></symbol>\n<symbol id=\"i-crosshair\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"7.5\"/><path d=\"M12 1.5v5M12 17.5v5M1.5 12h5M17.5 12h5\"/><circle cx=\"12\" cy=\"12\" r=\"1.6\" fill=\"currentColor\"/></symbol>\n<symbol id=\"i-chat\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 5.5h16v10.5H9l-5 4z\"/><path d=\"M8 9.5h8M8 12.5h5\"/></symbol>\n<symbol id=\"i-x\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\"><path d=\"M5 5l14 14M19 5L5 19\"/></symbol>\n<symbol id=\"i-pin\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2v8M8.5 10h7l2 4H6.5zM12 14v8\"/></symbol>\n<symbol id=\"i-play\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M7 4.5 19 12 7 19.5z\"/></symbol>\n<symbol id=\"i-dome\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 17a9 9 0 0 1 18 0\"/><path d=\"M3 17h18\"/><path d=\"M12 8v9\"/><path d=\"M7 11.5c1.5-1 3.2-1.5 5-1.5s3.5.5 5 1.5\"/></symbol>\n<symbol id=\"i-radar\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9.5\"/><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 12 19 6.5\"/><circle cx=\"12\" cy=\"12\" r=\"1.2\" fill=\"currentColor\"/></symbol>\n<symbol id=\"i-dl\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3v12M7 10.5l5 5 5-5M4 20h16\"/></symbol>\n<symbol id=\"i-gear\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3.2\"/><path d=\"M19.4 15a1.6 1.6 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.6 1.6 0 0 0-2.7 1.1v.3a2 2 0 1 1-4 0v-.2a1.6 1.6 0 0 0-2.8-1.1l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.6 1.6 0 0 0-1.1-2.7H3a2 2 0 1 1 0-4h.2A1.6 1.6 0 0 0 4.3 6.4l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.6 1.6 0 0 0 2.7-1.1V2a2 2 0 1 1 4 0v.2a1.6 1.6 0 0 0 2.7 1.1l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.6 1.6 0 0 0 1.1 2.7h.3a2 2 0 1 1 0 4h-.2a1.6 1.6 0 0 0-1.1 1.1Z\"/></symbol>\n<symbol id=\"i-moon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 13.2A8.6 8.6 0 1 1 10.8 3 6.9 6.9 0 0 0 21 13.2Z\"/></symbol>\n<symbol id=\"i-list\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"><path d=\"M8 6h13M8 12h13M8 18h13M3.5 6h.01M3.5 12h.01M3.5 18h.01\"/></symbol>\n</defs></svg>\n\n<!-- ═════ СТАРТ ═════ -->\n<div id=\"boot\" hidden></div>\n\n<!-- ═════ СЦЕНА ═════ -->\n<div id=\"stage\">\n  <video id=\"vid\" playsinline autoplay muted></video>\n  <canvas id=\"gl\" hidden></canvas>\n  <canvas id=\"ov\"></canvas>\n\n  <div id=\"hud\">\n    <div class=\"top\">\n      <!-- Стан підсистем окремими фішками. Раніше це був один довгий рядок\n           «ПН · АЗ 028.7° / 15° · GPS ±11 · мапа 2» — щоб прочитати його,\n           треба було зупинитись і розібрати, а під тривогою на це немає ні\n           секунди, ні голови. Тепер кожна підсистема має свою крапку, свою\n           назву і своє число, і поганий стан видно за кольором, не читаючи. -->\n      <div class=\"rail\" id=\"status\" data-s=\"bad\">\n        <div class=\"chip\" id=\"c-north\" data-s=\"bad\"><i></i><b>ПН</b><s>—</s></div>\n        <div class=\"chip\" id=\"c-gps\" data-s=\"bad\"><i></i><b>GPS</b><s>—</s></div>\n        <div class=\"chip wide\" id=\"c-data\" data-s=\"bad\"><i></i><b>ДАНІ</b><s>—</s></div>\n        <div class=\"chip wide\" id=\"c-ear\" data-s=\"mid\" hidden><i></i><b>СЛУХ</b><s>—</s></div>\n        <span id=\"st-text\" hidden></span>\n      </div>\n      <div class=\"ruler\"><canvas id=\"ruler\"></canvas></div>\n    </div>\n\n    <!-- Повідомлення живуть у нижньому краї НЕБА: над палубою, але не на\n         ній. Так вони не затуляють ні купол у центрі, ні цифри внизу. -->\n    <div class=\"sky\"><div class=\"hint\" id=\"hint\"></div><div id=\"toast\"></div></div>\n\n    <!-- Смуга демо — за умовчанням один рядок: небо важливіше за рамку про\n         показ. Дорожки типів розкриваються дотиком і згортаються так само. -->\n    <div id=\"demo-bar\" hidden>\n      <div class=\"demo-top\" id=\"demo-top\" role=\"button\" aria-expanded=\"false\">\n        <span class=\"tag\">ДЕМО</span>\n        <span class=\"txt\">не реальні дані</span>\n        <span class=\"left\" id=\"demo-left\">60 с</span>\n        <span class=\"more\" aria-hidden=\"true\"></span>\n      </div>\n      <div class=\"demo-track\"><div class=\"demo-fill\" id=\"demo-fill\"></div></div>\n      <div class=\"tl\">\n        <canvas id=\"demo-tl\"></canvas>\n        <div class=\"tl-scale\"><span>початок</span><span>зараз</span><span>кінець</span></div>\n      </div>\n    </div>\n    <div class=\"strip\" id=\"strip\"></div>\n\n    <!-- Палуба: одна картка в трьох станах. Тривога — не окрема смуга\n         десь поруч, а стан цієї ж картки: те саме місце екрана, куди\n         людина вже дивиться. За умовчанням — ОДИН рядок (дальність · тип ·\n         швидкість); дотик розкриває циферблат і подробиці. Стрічки каналу\n         тут більше немає — вона живе на власній сторінці; підписи джерел —\n         на радарі та в налаштуваннях. -->\n    <!-- БАЛІСТИКА: окрема смуга на весь екран. Без чисел і без розрахунків —\n         на них немає часу. Показується, поки є підстава (трек або\n         повідомлення), і ще три хвилини після. -->\n    <div class=\"bal\" id=\"bal\" hidden role=\"alert\">\n      <b>БАЛІСТИКА — В УКРИТТЯ НЕГАЙНО</b>\n      <span class=\"why\"></span>\n    </div>\n    <div class=\"deck empty compact\" id=\"deck\">\n      <div class=\"deck-alarm\" id=\"alarm\" hidden></div>\n      <div class=\"deck-main\" id=\"deck-main\" role=\"button\" aria-expanded=\"false\">\n        <canvas id=\"dial\" width=\"108\" height=\"108\"></canvas>\n        <div class=\"rd hero empty\" id=\"r-dist\">\n          <div class=\"k\">Дальність</div><div class=\"v\">—</div><div class=\"s\"></div>\n        </div>\n        <div class=\"deck-side\">\n          <div class=\"rd type empty\" id=\"r-type\"><div class=\"k\">Тип</div><div class=\"v\">—</div><div class=\"s\"></div></div>\n          <div class=\"rd empty\" id=\"r-spd\"><div class=\"k\">Швидкість</div><div class=\"v\">—</div><div class=\"s\"></div></div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"acts\">\n      <div class=\"act cam\" id=\"a-cam\"><svg><use href=\"#i-cam\"/></svg><span class=\"lbl\">камера</span></div>\n      <div class=\"act radar\" id=\"a-radar\" hidden><svg><use href=\"#i-radar\"/></svg><span class=\"lbl\">радар</span><span class=\"badge\" id=\"rad-badge\"></span></div>\n      <div class=\"act chat\" id=\"a-chat\" hidden><svg><use href=\"#i-chat\"/></svg><span class=\"lbl\">стрічка</span><span class=\"badge\" id=\"chat-badge\"></span></div>\n      <div class=\"act demo\" id=\"a-demo\" hidden><svg><use href=\"#i-play\"/></svg><span class=\"lbl\">демо</span></div>\n      <div class=\"act d9\" id=\"a-d9\" title=\"Зупинити купол і повернутись на мапу\"><svg><use href=\"#i-radar\"/></svg><span class=\"lbl\">Закрити</span></div>\n      <div class=\"act set\" id=\"a-set\"><svg><use href=\"#i-gear\"/></svg><span class=\"lbl\">налашт.</span></div>\n    </div>\n  </div>\n</div>\n\n<!-- ═════ РАДАР ═════ -->\n<!-- ═════ СМУГА ДЕМО ═════ -->\n\n<div id=\"radar\">\n  <div class=\"rd-top\">\n    <svg style=\"width:20px;height:20px;color:var(--acc)\"><use href=\"#i-radar\"/></svg>\n    <h2>МАПА</h2>\n    <div class=\"sub\" id=\"rd-sub\">—</div>\n    <button class=\"x-btn\" id=\"rd-x\" title=\"Назад\" aria-label=\"Назад\">\n      <svg><use href=\"#i-x\"/></svg></button>\n  </div>\n  <div class=\"map-wrap\">\n    <canvas id=\"rdr\"></canvas>\n    <div class=\"map-ctl\">\n      <button id=\"map-in\" aria-label=\"Ближче\">+</button>\n      <button id=\"map-out\" aria-label=\"Далі\">−</button>\n      <button id=\"map-auto\" class=\"auto on\" aria-label=\"Автомасштаб\">АВТО</button>\n    </div>\n  </div>\n  <div class=\"tl-wrap\">\n    <div class=\"tl-head\">\n      <span id=\"tl-when\">ЗАРАЗ · наживо</span>\n      <button class=\"tl-live\" id=\"tl-live\">НАЖИВО</button>\n    </div>\n    <canvas id=\"tl-c\"></canvas>\n    <div class=\"tl-scale\"><span>-24 год</span><span>-12</span><span>-6</span><span>зараз</span></div>\n  </div>\n  <div class=\"credit\" id=\"rd-credit\"></div>\n  <div class=\"rd-body\" id=\"rd-body\"></div>\n  <div class=\"arch\" id=\"arch\"></div>\n  <div class=\"rd-acts\">\n    <button class=\"btn sm\" id=\"rd-report\"><svg><use href=\"#i-chat\"/></svg>Доповісти</button>\n    <button class=\"btn sm\" id=\"rd-tri\"><svg><use href=\"#i-target\"/></svg>Спільний фікс</button>\n    <button class=\"btn sm ghost\" id=\"rd-export\"><svg><use href=\"#i-dl\"/></svg>Експорт</button>\n  </div>\n</div>\n\n<!-- ═════ СТРІЧКА (ЧАТ) ═════ -->\n<div id=\"chat\" class=\"page\">\n  <div class=\"rd-top\">\n    <svg style=\"width:20px;height:20px;color:var(--acc)\"><use href=\"#i-chat\"/></svg>\n    <h2>СТРІЧКА</h2>\n    <div class=\"sub\" id=\"chat-sub\"></div>\n    <button class=\"x-btn\" id=\"chat-x\" title=\"Назад\" aria-label=\"Назад\">\n      <svg><use href=\"#i-x\"/></svg></button>\n  </div>\n  <div class=\"wire\" id=\"wire\" hidden></div>\n  <div class=\"wire-empty\" id=\"wire-empty\">Повідомлень ще немає — джерела підключаються.</div>\n</div>\n\n<!-- ═════ СЛУЖБОВА ПАНЕЛЬ ═════ -->\n<div id=\"svc-scrim\"></div>\n<div id=\"svc\">\n  <div class=\"pg-top\">\n    <h2>НАЛАШТУВАННЯ</h2>\n    <button class=\"x-btn\" id=\"svc-x\" title=\"Назад\" aria-label=\"Назад\">\n      <svg><use href=\"#i-x\"/></svg></button>\n  </div>\n  <div class=\"tabs\" id=\"svc-tabs\">\n    <button class=\"tab on\" data-tab=\"sens\">Давачі</button>\n    <button class=\"tab\" data-tab=\"src\" hidden>Джерела</button>\n    <button class=\"tab\" data-tab=\"look\">Вигляд</button>\n    <button class=\"tab\" data-tab=\"sys\">Система</button>\n  </div>\n\n  <div class=\"pane on\" data-pane=\"sens\">\n    <div class=\"sect\">Самоперевірка</div>\n    <div class=\"card\" id=\"svc-check\"></div>\n    <div class=\"sect\">Орієнтація — куди дивиться камера</div>\n    <div class=\"card\" id=\"svc-ori\"></div>\n    <div class=\"grid2\" style=\"margin-top:8px\">\n      <button class=\"btn sm\" id=\"svc-retry\"><svg><use href=\"#i-gyro\"/></svg>Дозвіл на давачі</button>\n      <button class=\"btn sm\" id=\"svc-north\">Прив'язати північ</button>\n      <button class=\"btn sm ghost\" id=\"svc-flip\">Північ навпаки</button>\n    </div>\n    <div class=\"sect\">Оптика</div>\n    <div class=\"card\" id=\"svc-opt\"></div>\n    <div class=\"sect\">Позиція і детектор</div>\n    <div class=\"card\" id=\"svc-pos\"></div>\n    <div class=\"card\" style=\"margin-top:8px\">\n      <div class=\"row\"><label>Економний детектор <small>менше грію батарею, гірше видно дрібні цілі</small></label><div class=\"sw\" id=\"sw-eco\"></div></div>\n    </div>\n  </div>\n\n  <div class=\"pane\" data-pane=\"src\" hidden>\n    <div class=\"sect\">Мережеві дані</div>\n    <div class=\"card\">\n      <div class=\"row\"><label>Зовнішні дані <small>повітряна обстановка з відкритих джерел · потребує інтернету</small></label><div class=\"sw on\" id=\"sw-feed\"></div></div>\n      <div class=\"row\"><label>Цивільні борти <small>ADS-B: щоб не приймати літак за ціль · над Україною небо закрите, з телефона джерело не відповідає — вмикається, якщо відповість</small></label><div class=\"sw\" id=\"sw-adsb\"></div></div>\n      <div class=\"row\"><label>Архів атак <small>історія нальотів і тривог за роки · відкриті набори, ~2 МБ</small></label><div class=\"sw\" id=\"sw-arch\"></div></div>\n      <div class=\"row\"><label>Непевні треки <small>одне джерело, позиція приблизна чи домальована за курсом, у стрічці про неї ані слова · <b>ховати</b> (типово) — лише підтверджені · <b>тьмяно</b> — кільце без підпису · <b>як є</b> — як цілі</small></label>\n        <div class=\"seg\" id=\"seg-loose\"><button data-m=\"faint\">тьмяно</button><button data-m=\"hide\">ховати</button><button data-m=\"all\">як є</button></div></div>\n      <div class=\"row\"><label>Непідтверджені цілі <small>джерело каже «спостерігачі мовчать» (stale) — за умовчанням такі на купол не йдуть</small></label><div class=\"sw\" id=\"sw-stale\"></div></div>\n      <div class=\"row\"><label>Радіус даних <small>цілі далі за це на купол не йдуть; типово 50 км — те, що людині в укритті ще є сенс дивитись</small></label>\n        <div class=\"seg\" id=\"seg-radius\"><button data-r=\"50\">50</button><button data-r=\"100\">100</button><button data-r=\"150\">150</button><button data-r=\"250\">250</button></div></div>\n    </div>\n    <div class=\"card\" id=\"svc-feed\" style=\"margin-top:8px\"></div>\n    <div class=\"sect\">Джерела даних</div>\n    <div class=\"credit src\" id=\"src-credit\"></div>\n    <div class=\"card\" id=\"svc-src\"></div>\n    <div class=\"grid2\" style=\"margin-top:8px\">\n      <button class=\"btn sm ghost\" id=\"svc-srctest\"><svg><use href=\"#i-radar\"/></svg>Перевірити</button>\n      <button class=\"btn sm ghost\" id=\"svc-import\"><svg><use href=\"#i-dl\"/></svg>Знімок вручну</button>\n    </div>\n  </div>\n\n  <div class=\"pane\" data-pane=\"look\">\n    <div class=\"sect\">Оповіщення</div>\n    <div class=\"card\">\n      <div class=\"row\"><label>Голос <small>офлайновий синтез мови телефона: нова ціль, курс на вас і час, балістика, мовчання даних · без мережі · якщо мовчить або говорить не українською — iPhone: Параметри → Доступність → Вимовлений контент → Голоси → Українська</small></label><div class=\"sw on\" id=\"sw-voice\"></div></div>\n      <div class=\"row\"><label>Працювати з погашеним екраном <small>петля тиші тримає сторінку живою у фоні; голос і вібрація продовжують · їсть батарею · це не пуш — пуш без сервера неможливий</small></label><div class=\"sw\" id=\"sw-bg\"></div></div>\n    </div>\n    <div class=\"sect\">Купол і екран</div>\n    <div class=\"card\">\n      <div class=\"row\"><label>Нічний режим <small>червона палітра</small></label><div class=\"sw\" id=\"sw-night\"></div></div>\n      <div class=\"row\"><label>Купольна сітка <small>меридіани і висотні кільця</small></label><div class=\"sw on\" id=\"sw-grid\"></div></div>\n      <div class=\"row\"><label>Купол у 3D <small>WebGL: глибина, світіння, промені до горизонту</small></label><div class=\"sw\" id=\"sw-gl\"></div></div>\n    </div>\n    <div class=\"sect\">Шари купола</div>\n    <div class=\"note\">Кожен шар вимикається окремо. Увага в укритті витратна — якщо чогось\n      забагато, лишай голе небо з цілями.</div>\n    <div class=\"card\">\n      <div class=\"row\"><label>Небо <small>сонце і конус засліплення, Місяць із фазою, сутінки й таймер, межа підсвітки (вище неї ціль ще освітлена сонцем на темному небі), Полярна як еталон півночі · рахується з координат і годинника, без мережі</small></label><div class=\"sw on\" id=\"sw-sky\"></div></div>\n      <div class=\"row\"><label>Горизонт загрози <small>дуги по азимутах: скільки цілей іде звідти і за скільки хвилин найближча вийде з-за обрію · знизу тьмяний слід — якими напрямками заходили раніше</small></label><div class=\"sw on\" id=\"sw-ring\"></div></div>\n      <div class=\"row\"><label>Коридор прольоту <small>стрічка прогнозу з зіркою в точці найближчого підходу і підписом «скільки метрів через скільки секунд» · тут же напрямок на напарника</small></label><div class=\"sw on\" id=\"sw-corr\"></div></div>\n      <div class=\"row\"><label>Слух <small>акустичний горизонт (де гучніше — «на слух», не дані), спектрограма 40–2000 Гц і звукова затримка: звук із 5 км іде 15 с, тож ціль уже не там, звідки чути</small></label><div class=\"sw on\" id=\"sw-ear\"></div></div>\n      <div class=\"row\"><label>Слід сканування <small>сектори, у які ти вже дивився, гаснуть; недивлені лишаються підсвіченими — карта власної уваги</small></label><div class=\"sw on\" id=\"sw-scan\"></div></div>\n      <div class=\"row\"><label>Спалах і грім <small>яскравий спалах у кадрі плюс бахкання в мікрофоні: різниця часу × 340 м/с = дальність влучання · потрібна камера</small></label><div class=\"sw on\" id=\"sw-flash\"></div></div>\n      <div class=\"row\"><label>Теплова карта руху <small>де за останню хвилину детектор бачив рух · потрібна камера, тому типово вимкнено</small></label><div class=\"sw\" id=\"sw-heat\"></div></div>\n    </div>\n    <div class=\"sect\" hidden>Демонстрація</div>\n    <div class=\"note\" hidden>Кнопка <b>«демо»</b> — у нижньому меню. Хвилина згенерованої обстановки,\n      сім класів цілей: поршневий «шахед» і реактивна «Герань-3» поруч, крилата, балістична,\n      гіперзвукова, БпЛА-«крило», FPV і цивільний борт. Знизу — таймлайн показу: видно, що і\n      коли пролетить. Камера й мережа на цей час не потрібні — купол крутиться сам.</div>\n  </div>\n\n  <div class=\"pane\" data-pane=\"sys\">\n    <div class=\"sect\">Дозволи</div>\n    <div class=\"card\" id=\"svc-perms\"></div>\n    <div class=\"sect\">Режим запуску</div>\n    <div class=\"card\" id=\"svc-standalone\"></div>\n    <div class=\"sect\">Чорна скринька</div>\n    <div class=\"card\" id=\"svc-bb\"></div>\n    <div style=\"height:8px\"></div>\n    <button class=\"btn sm\" id=\"svc-bb-save\"><svg><use href=\"#i-dl\"/></svg>Зберегти чорну скриньку</button>\n    <div class=\"sect\">Дані застосунку</div>\n    <button class=\"btn sm\" id=\"svc-drop\">Скинути цілі</button>\n    <div style=\"height:8px\"></div>\n    <button class=\"btn sm ghost\" id=\"svc-reset\">Скинути все і перезапустити</button>\n    <div class=\"sect\">Про</div>\n    <div class=\"card\">\n      <div class=\"note\">Купол · модуль delta9. Цілі — зі зведеного потоку delta9 (mapa.ua + NEPTUN), позиція і дозволи — з delta9.<br><br>\n      Тип цілі, її розмір, висота і ракурс НЕ задаються вручну: система перебирає типи з каталогу і лишає той, у якого дальність, висота і швидкість не суперечать його ТТХ. Фокусна відстань камери калібрується сама — за тим, як зсувається картинка під час повороту телефона.</div>\n      <div style=\"height:8px\"></div>\n      <button class=\"btn sm ghost\" id=\"svc-sources\"><svg><use href=\"#i-list\"/></svg>Джерела ТТХ</button>\n    </div>\n  </div>\n  <div style=\"height:10px\"></div>\n</div>\n\n<div id=\"modal\"><div class=\"mwrap\">\n  <button class=\"x-btn\" id=\"m-x\" title=\"Закрити\" aria-label=\"Закрити\"><svg><use href=\"#i-x\"/></svg></button>\n  <div class=\"mbox\" id=\"mbox\"></div>\n</div></div>\n";
