  cam: { stream: null, track: null, w: 0, h: 0, zoom: 1, zoomCaps: null, ready: false },
  fpx: 0, fovSrc: 'default',
  q: [0, 0, 0, 1], qRaw: [0, 0, 0, 1],
  radarOpen: false, radarRange: 5000,
  aimId: null, aimFeedId: null, aimKey: null, aimT: 0,   // що в прицілі (своє / мережеве) і коли змінилось
