    srcCount: +o.sourceCount || (Array.isArray(o.sources) ? o.sources.length : 0) || 1,
    count: +o.count || 1,
    approx: estimated, note: o.summary || o.text || o.description || '',
    /* Куди, за розрахунком карти, ціль прямує. Це не наша оцінка, а їхня —
       тому підписуємо як передбачення і не малюємо там позначку. */
    dest: (o.destinationLat != null && o.destinationLng != null)
      ? { lat: +o.destinationLat, lon: +o.destinationLng, name: o.destination || '' } : null,
