  ORI.headFlip = S.set.headFlip || 0;
  ORI.headAxis = S.set.headAxis === 'cam' ? 'cam' : 'fwd';
  S.set.noCam = true;              // єдиний режим: купол; камера — інструмент
  applyNoCam(true);
